    ("LOC_PROJECT_CREATE_PRODUCT_KHALIFA_SHORT_NAME",                 "[ICON_DISTRICT_WONDER] Create new Unique [ICON_RESOURCE_KHALIFA] Product of Burj Khalifa®"),
    ("LOC_PROJECT_CREATE_PRODUCT_KHALIFA_DESCRIPTION",                "Allows creation of unique [ICON_RESOURCE_KHALIFA] Products (max. 8) when [ICON_DISTRICT_WONDER] Burj Khalifa is built."),
    ("LOC_HD_PEDIA_CATEGORY_KHALIFA_NAME",                            "[ICON_DISTRICT_WONDER] Burj Khalifa® Unique [ICON_RESOURCE_KHALIFA] Product"),
    
    ("LOC_GREATWORK_PRODUCT_KHALIFA_1_NAME",                          "Dubai Dried Date"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_2_NAME",                          "Roast Camel"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_3_NAME",                          "Hand-made Pistachio Ice-cream"),
    ("LOC_GREATWORK_PRODUCT_KHALIFA_4_NAME",                          "Arabica coffee"),
