    ("LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_1_BONUS",                   "+15% [ICON_FOOD] food to this city."),
    ("LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_2_BONUS",                   "[ICON_FOOD] Food consumption of citizens in this city reduce by 0.5."),
    ("LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_3_BONUS",                   "+4 [ICON_AMENITIES] Amenity to this city."),
    ("LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_4_BONUS",                   "Citizens in this city provide +0.3 [ICON_SCIENCE] Science and [ICON_CULTURE] Culture."),
    ("LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_5_BONUS",                   "+100% Campuss district adjacency bonuses to this city."),
