	('1'),('2'),('3'),('4'),('5'),('6'),('7'),('8');

update LocalizedText set Text = Text || "{LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_DESCRIPTION}" where Tag = "LOC_PEDIA_CONCEPTS_PAGE_MONOPOLIES_CHAPTER_PRODUCTS_PARA_1";
update LocalizedText set Text = Text || 
    (select GROUP_CONCAT("[NEWLINE][ICON_RESOURCE_KHALIFA] {LOC_GREATWORK_PRODUCT_KHALIFA_" || Num ||"_NAME}: {LOC_PEDIA_GREATWORK_PRODUCT_KHALIFA_"|| Num ||"_BONUS}","") from HD_KHALIFA_Products)
    where Tag = "LOC_PEDIA_CONCEPTS_PAGE_MONOPOLIES_CHAPTER_PRODUCTS_PARA_1";